#include <iostream>
#include <vector>

using namespace std;

/**
 * Problem: 10501 - Safe Salutations
 * 
 * 解題思路：
 * 這是一個典型的卡特蘭數 (Catalan Number) 問題。
 * 當有 2n 個人圍成一圈握手且手不可交叉時，可能的握手方式數量即為第 n 個卡特蘭數 C_n。
 * 卡特蘭數的遞迴公式為：
 * C_0 = 1
 * C_n = Σ (C_i * C_{n-1-i})，其中 i 從 0 到 n-1
 * 
 * 給定 n 的範圍是 1 到 10，我們可以直接預處理或動態規劃計算。
 */

int main() {
    int n;
    bool first = true;

    // 預處理卡特蘭數
    vector<long long> catalan(11, 0);
    catalan[0] = 1;
    for (int i = 1; i <= 10; ++i) {
        for (int j = 0; j < i; ++j) {
            catalan[i] += catalan[j] * catalan[i - 1 - j];
        }
    }

    // 讀取輸入直到結束
    while (cin >> n) {
        // 題目要求在測試資料集之間輸出一個空行
        if (!first) {
            cout << endl;
        }
        first = false;

        // 輸出第 n 個卡特蘭數
        cout << catalan[n] << endl;
    }

    return 0;
}
